<?php

/* @autogenerated */
declare(strict_types=1);

namespace Civi\Lughauth\Bootstrap\Plugin;

use Override;
use Cron\CronExpression;
use Psr\Container\ContainerInterface;
use Civi\Lughauth\Bootstrap\Management\Apidoc\ApidocManagement;
use Civi\Lughauth\Bootstrap\Management\Audit\AuditManagement;
use Civi\Lughauth\Shared\Infrastructure\MicroPlugin;
use Civi\Lughauth\Bootstrap\Management\Health\HealthManagement;
use Civi\Lughauth\Bootstrap\Management\Metrics\MetricsManagement;
use Civi\Lughauth\Bootstrap\Management\Migration\MigrationManagement;
use Civi\Lughauth\Bootstrap\Management\Config\ConfigManagement;
use Civi\Lughauth\Bootstrap\Management\Dependencies\DependenciesManagement;
use Civi\Lughauth\Bootstrap\Management\Log\LogManagement;
use Civi\Lughauth\Bootstrap\Management\Routes\RoutesManagement;
use Civi\Lughauth\Bootstrap\Management\Trace\TraceManagement;
use Civi\Lughauth\Bootstrap\Management\Collector\LogCollector;
use Civi\Lughauth\Bootstrap\Management\Collector\TraceCollector;
use Civi\Lughauth\Bootstrap\Management\EntityChangelog\LoadChangesManagement;
use Civi\Lughauth\Bootstrap\Management\EntityChangelog\MarkAckManagement;
use Civi\Lughauth\Bootstrap\Management\EntityChangelog\UpdateChangelogManagement;
use Civi\Lughauth\Bootstrap\Management\Histogram\HistogramManagement;
use Civi\Lughauth\Bootstrap\Management\History\HistoryManagement;
use Civi\Lughauth\Bootstrap\MicroConfig;
use Civi\Lughauth\Bootstrap\Middleware\Metrics\PrometheusRegistryExporter;
use Civi\Lughauth\Shared\Infrastructure\Scheduler\SchedulerManager;
use Civi\Lughauth\Shared\Infrastructure\StartupProcessor;

/**
 * Registers management endpoints and scheduled maintenance tasks.
 */
class ManagementPlugin extends MicroPlugin
{
    /**
     * Registers the metrics export scheduler.
     */
    #[Override]
    public function registerSchedulers(SchedulerManager $scheduler): void
    {
        $scheduler->register(new CronExpression('*/15 * * * *'), PrometheusRegistryExporter::class, "forceDump");
    }

    /**
     * Resolves management interfaces based on configuration flags.
     */
    #[Override]
    public function getManagementsInterfaces(ContainerInterface $container): array
    {
        $all = [];
        $def = $container->get(MicroConfig::class);
        $all[] = $container->get(HealthManagement::class);
        $all[] = $container->get(ConfigManagement::class);
        $all[] = $container->get(RoutesManagement::class);
        $all[] = $container->get(DependenciesManagement::class);
        if ($def->withMetrics) {
            $all[] = $container->get(MetricsManagement::class);
        }
        $all[] = $container->get(MigrationManagement::class);
        $all[] = $container->get(ApidocManagement::class);
        if ($def->withTelemetry) {
            $all[] = $container->get(LogManagement::class);
            $all[] = $container->get(TraceManagement::class);
            $all[] = $container->get(TraceCollector::class);
            $all[] = $container->get(LogCollector::class);
        }
        if ($def->withAudit) {
            $all[] = $container->get(HistoryManagement::class);
            $all[] = $container->get(AuditManagement::class);
        }
        $all[] = $container->get(HistogramManagement::class);
        $all[] = $container->get(LoadChangesManagement::class);
        $all[] = $container->get(MarkAckManagement::class);
        $all[] = $container->get(UpdateChangelogManagement::class);
        return $all;
    }

    /**
     * Registers startup tasks for running migrations.
     */
    #[Override]
    public function registerStartup(StartupProcessor $processor): void
    {
        $processor->register(function (ContainerInterface $container) {
            $migrations = $container->get(MigrationManagement::class);
            $callback = $migrations->set();
            $callback();
        });
    }
}
